C++ Code:
#include<iostream>
using namespace std;
int main()
{
   int n, first = 0, second = 1, next, i;
   cout << "Enter the number of terms you want: ";
   cin >> n;
   cout << "First " << n << " terms of Fibonacci series are: ";
   for (i = 0; i < n; i++)
   {
      if (i <= 1)
         next = i;
      else
      {
         next = first + second;
         first = second;
         second = next;
      }
      cout << next << " ";
   }
   return 0;
}

